  "signal_basis": {
    "component_id": "C035.signal_basis",
    "value": "Cross-checking record identifiers, amounts, scope, people and dates may reveal conflicting dates or mismatched amounts or identities that signal uncertainty.",
    "scope": "Proposed checks and possible findings, assumed observed for this assessment; discrepancies do not identify which record, if any, is inaccurate.",
